# We'll try to assign vertices to 3 color classes and then add edges between classes.
# To avoid triangles, we must ensure that for any triple of vertices from different classes, not all three edges are present.
# To avoid 4-cycles, we need to avoid having two vertices in one class both connected to two vertices in another class (forming a K_{2,2}).

# Let's try a random search with backtracking.

import random

def has_cycle_of_length(edges, length):
    # Check if there is a cycle of given length using BFS/DFS limited depth
    # Build adjacency
    adj = {i: set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # For length 3: check if any edge has a common neighbor
    if length == 3:
        for u,v in edges:
            common = adj[u] & adj[v]
            if common:
                return True
        return False

    # For length 4: check for paths of length 2 between two vertices that are not directly connected
    if length == 4:
        for u in range(n):
            for v in range(u+1, n):
                if v in adj[u]:
                    continue
                # count common neighbors
                common = adj[u] & adj[v]
                if len(common) >= 2:
                    return True
        return False

    return False

def girth_at_least(edges, g):
    for l in range(3, g):
        if has_cycle_of_length(edges, l):
            return False
    return True

def is_3_colorable(edges):
    # Use simple backtracking
    adj = {i: set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1]*n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

