def greedy_search():
    edges = []
    # Order vertices randomly
    verts = list(range(n))
    random.shuffle(verts)

    # Try to add edges
    for _ in range(10000):
        u = random.randrange(n)
        v = random.randrange(n)
        if u >= v:
            continue
        if (u,v) in edges or (v,u) in edges:
            continue
        # Try adding
